part of 'project.dart';

class GeneratedFileChange {
  const GeneratedFileChange(
    this.path,
    this.kind,
    this.beforeExecutable,
    this.executable,
  );
  final String path, kind;
  final bool beforeExecutable, executable;
  Map<String, Object?> toJson() => {
    'path': path,
    'kind': kind,
    'beforeExecutable': beforeExecutable,
    'executable': executable,
  };
}

/// Frozen generated bytes use the existing directory receipt and publication
/// guard. Neither generation nor publication mutates canonical source.
class ClientOutput extends BundleOutput {
  ClientOutput._(
    BusyProject owner,
    _OutputInput input,
    Map<String, List<int>> files,
    Map<String, String> digests,
    Set<String> executables,
    Map<String, Object?> metadata,
    this.messages,
  ) : _files = Map.unmodifiable(files),
      _executables = Set.unmodifiable(executables),
      _digests = Map.unmodifiable(digests),
      super._(
        owner,
        input.access,
        input.target,
        input.snapshot,
        input.saved,
        input.checked['unsaved'] == true,
        input.revision,
        {
          'output': {'identity': metadata['outputIdentity']},
        },
        metadata,
      );
  final Map<String, List<int>> _files;
  final Map<String, String> _digests;
  final Set<String> _executables;
  final String messages;
  List<String> get files => List.unmodifiable(_files.keys.toList()..sort());
  List<int> bytes(String name) =>
      _files[name] ??
      (throw CoreFailure('generate.file', 'Select a captured generated file'));
  Future<List<int>?> previousBytes(String name, String receiptIdentity) async {
    if (!AtomicDirectoryWriter.safeName(name))
      throw CoreFailure('generate.file', 'Invalid generated file selection');
    final receipt = await existing();
    if (receipt?.identity != receiptIdentity)
      throw OutputDirectoryChanged(destination);
    if (!receipt!.files.containsKey(name)) return null;
    final bytes = await _access.read(p.join(destination, name));
    if (await contentIdentityAsync(bytes) != receipt.files[name] ||
        (await existing())?.identity != receiptIdentity)
      throw OutputDirectoryChanged(destination);
    return bytes;
  }

  @override
  Future<OutputDirectoryReceipt?> existing() async {
    final receipt = await super.existing();
    if (receipt != null && receipt.metadata['operation'] != 'generate') {
      throw CoreFailure(
        'generate.ownership',
        'Choose another destination; this output is not an unchanged BusyAPI-generated client',
      );
    }
    return receipt;
  }

  Future<List<GeneratedFileChange>> changes(
    OutputDirectoryReceipt? existing,
  ) async {
    final result = <GeneratedFileChange>[];
    final paths = {..._files.keys, ...?existing?.files.keys}.toList()..sort();
    for (final path in paths) {
      final current = _files[path], previous = existing?.files[path];
      final beforeExecutable =
              (existing?.metadata['executables'] as List? ?? []).contains(path),
          executable = _executables.contains(path);
      result.add(
        GeneratedFileChange(
          path,
          current == null
              ? 'removed'
              : previous == null
              ? 'added'
              : _digests[path] == previous && beforeExecutable == executable
              ? 'unchanged'
              : 'changed',
          beforeExecutable,
          executable,
        ),
      );
    }
    return List.unmodifiable(result);
  }

  @override
  Future<OutputDirectoryResult> publish({
    String? replaceIdentity,
    bool Function()? cancelled,
    FutureOr<void> Function()? beforePublish,
    FutureOr<void> Function()? afterPublish,
  }) {
    if (_closed)
      throw CoreFailure('output.closed', 'The frozen client output is closed');
    return _access.publishOutput(
      destination,
      _files,
      metadata,
      replaceIdentity: replaceIdentity,
      cancelled: cancelled,
      beforePublish: beforePublish,
      afterPublish: afterPublish,
      executableFiles: _executables,
    );
  }
}

Future<
  ({
    Map<String, List<int>> files,
    Map<String, String> digests,
    Set<String> executables,
  })
>
_captureGeneratedFiles(String directory) => Isolate.run(() async {
  final result = <String, List<int>>{};
  final digests = <String, String>{};
  final executables = <String>{};
  var total = 0;
  await for (final file in Directory(
    directory,
  ).list(recursive: true, followLinks: false)) {
    final name = p
        .relative(file.path, from: directory)
        .replaceAll(p.separator, '/');
    if (!AtomicDirectoryWriter.safeName(name) ||
        file is Link ||
        file is! File && file is! Directory) {
      throw CoreFailure(
        'generate.path',
        'Generator output contains an escaping, linked or special entry',
      );
    }
    if (file is! File) continue;
    final size = await file.length();
    total += size;
    if (size > 16 * 1024 * 1024 ||
        total > AtomicDirectoryWriter.maxBytes ||
        result.length >= AtomicDirectoryWriter.maxFiles - 2) {
      throw CoreFailure(
        'generate.limit',
        'Generated files exceed the bounded output budget',
      );
    }
    if (name == AtomicDirectoryWriter.receiptName ||
        name == 'busyapi-generation.json' ||
        name == 'BUSYAPI-GENERATION-NOTICE.txt') {
      throw CoreFailure(
        'generate.path',
        'Generator output collides with BusyAPI ownership metadata',
      );
    }
    result[name] = Uint8List.fromList(await file.readAsBytes())
        .asUnmodifiableView();
    digests[name] = contentIdentity(result[name]!);
    if ((await file.stat()).mode & 0x49 != 0) executables.add(name);
  }
  if (result.isEmpty)
    throw CoreFailure(
      'generate.incomplete',
      'The generator produced no client files',
    );
  return (
    files: result,
    digests: {
      for (final name in digests.keys.toList()..sort()) name: digests[name]!,
    },
    executables: executables,
  );
});

extension ClientGeneration on BusyProject {
  Future<ClientOutput> prepareClient(
    String root,
    String destination, {
    required String generator,
    Map<String, Object?> options = const {},
    String? templateDirectory,
    GeneratorRuntime? runtime,
    bool saved = false,
    String? requestId,
    bool Function()? cancelled,
    void Function(String resource)? onResourceRefreshed,
  }) async {
    // Capture caller-owned containers before any asynchronous work.
    final selectedOptions = Map<String, Object?>.from(
      jsonDecode(jsonEncode(options)) as Map,
    );
    if (jsonEncode(selectedOptions).length > 65536)
      throw CoreFailure('generate.options', 'Generator options exceed 64 KiB');
    final tool = runtime ?? GeneratorRuntime();
    final documented = await tool.options(generator, cancelled: cancelled);
    final allowed = documented.map((option) => option.name).toSet();
    if (selectedOptions.keys.any(
      (key) =>
          !allowed.contains(key) ||
          [
            'enablePostProcessFile',
            'templateDir',
            'outputDir',
            'skipValidateSpec',
          ].contains(key),
    )) {
      throw CoreFailure(
        'generate.options',
        'Only the selected generator’s documented non-executable options are accepted',
      );
    }
    if (allowed.contains('hideGenerationTimestamp'))
      selectedOptions.putIfAbsent('hideGenerationTimestamp', () => true);
    final captured = await _captureOutputInput(
      root,
      destination,
      operation: 'generate',
      saved: saved,
      requestId: requestId,
      cancelled: cancelled,
      onResourceRefreshed: onResourceRefreshed,
    );
    Directory? stage;
    try {
      if (templateDirectory != null) {
        final templates = p.normalize(p.absolute(templateDirectory));
        if (templates == captured.target ||
            p.isWithin(templates, captured.target) ||
            p.isWithin(captured.target, templates)) {
          throw CoreFailure(
            'output.source',
            'Choose an output separate from the captured template directory',
          );
        }
      }
      final contract = await _deriveContract(
        captured,
        Uri.file(p.join(captured.target, 'openapi.json')).toString(),
        requestId: requestId,
        cancelled: cancelled,
      );
      stage = await Directory.systemTemp.createTemp('busyapi-client-');
      privatePermissions(stage.path, 448);
      final entry = File(p.join(stage.path, 'openapi.json'));
      await entry.writeAsString(
        contract.result['output']['text'] as String,
        flush: true,
      );
      final configuration = File(p.join(stage.path, 'options.json'));
      await configuration.writeAsString(
        jsonEncode({'additionalProperties': selectedOptions}),
        flush: true,
      );
      final templateIdentities = <String, String>{};
      if (templateDirectory != null) {
        final templates = await ProjectAccess.open(templateDirectory);
        var total = 0;
        try {
          await for (final entry in Directory(
            templates.boundary,
          ).list(recursive: true, followLinks: false)) {
            if (entry is Link || entry is! File && entry is! Directory)
              throw CoreFailure(
                'generate.templates',
                'Template overrides must contain only regular files and directories',
              );
            if (entry is! File) continue;
            final name = p.relative(entry.path, from: templates.boundary);
            final bytes = await templates.read(entry.path);
            total += bytes.length;
            if (total > 32 * 1024 * 1024 || templateIdentities.length >= 1024)
              throw CoreFailure(
                'generate.limit',
                'Template overrides exceed the capture budget',
              );
            final copied = File(p.join(stage.path, 'templates', name));
            await copied.parent.create(recursive: true);
            await copied.writeAsBytes(bytes);
            templateIdentities[name] = await contentIdentityAsync(bytes);
          }
        } finally {
          templates.close();
        }
      }
      final output = p.join(stage.path, 'output');
      final result = await tool.run(stage.path, [
        'generate',
        '-g',
        generator,
        '-i',
        entry.path,
        '-o',
        output,
        '-c',
        configuration.path,
        '--global-property',
        'debugOperations=true',
        if (templateDirectory != null) ...[
          '--template-dir',
          p.join(stage.path, 'templates'),
        ],
      ], cancelled: () => _closed || cancelled?.call() == true);
      String sanitize(String value) => _sanitizeMockText(
        utf8.encode(value.replaceAll(stage!.path, '[stage]')),
        access.boundary,
      );
      if (result.exitCode != 0) {
        final unsupported =
            result.exitCode == 2 ||
            RegExp(
              r'SpecValidationException|java\.lang\.Boolean cannot be cast',
            ).hasMatch('${result.errors}\n${result.output}');
        throw GeneratorFailure(
          unsupported ? 'generate.incomplete' : 'generate.failed',
          'OpenAPI Generator did not complete (exit ${result.exitCode}); no client can be published',
          detail: sanitize('${result.errors}\n${result.output}'),
        );
      }
      final coverage = await generatorCoverageAsync(result.output);
      final expected = <String>{};
      for (final operation
          in captured.checked['projection']['operations'] as List) {
        final key =
            httpOperationMethod(operation as Map) + ' ${operation['path']}';
        if (operation['role'] != 'operation' ||
            !coverage.operations.contains(key)) {
          throw GeneratorFailure(
            'generate.coverage',
            operation['role'] != 'operation'
                ? 'This adapter cannot prove callback or webhook conversion coverage; output was withheld'
                : 'The generator omitted an authored operation; output was withheld',
            detail: sanitize('$key (${operation['role']})'),
          );
        }
        expected.add(key);
      }
      if (_closed || cancelled?.call() == true)
        throw CoreFailure('cancelled', 'Client generation cancelled');
      final generated = await _captureGeneratedFiles(output);
      final files = generated.files, digests = generated.digests;
      final receipt = await tool.verify();
      String portable(String id) {
        final uri = Uri.parse(id);
        return uri.scheme == 'file' &&
                p.isWithin(access.boundary, uri.toFilePath())
            ? './${p.relative(uri.toFilePath(), from: access.boundary)}'
            : 'resource:${textIdentity(id)}';
      }

      final metadata = <String, Object?>{
        'version': 1,
        'operation': 'generate',
        'adapterVersion': '1',
        'generator': generator,
        'generatorVersion': generatorVersion,
        'engine': engine.assetIdentity,
        'bundler': {
          'producer': contract.result['producer'],
          'version': contract.result['producerVersion'],
          'identity': contract.result['output']['identity'],
        },
        'launcher': receipt['files']['generator-launcher'],
        'jar': generatorJarIdentity,
        'runtimeArchive': generatorRuntimeArchive,
        'runtimeFiles': textIdentity(jsonEncode(receipt['files'])),
        'root': portable(root),
        'snapshot': captured.snapshot.sourceIdentity,
        'input': captured.checked['unsaved'] == true
            ? 'working-copy'
            : 'saved-source',
        'options': selectedOptions,
        'executables': generated.executables.toList()..sort(),
        'templates': templateIdentities,
        'sources': [
          for (final resource in captured.snapshot.resources)
            {
              'resource': portable(resource['id'] as String),
              'identity': resource['identity'],
            },
        ],
        'operations': expected.toList()..sort(),
        'coverage': 'official generator operation conversion; generated code is not compiled or executed by BusyAPI',
        'outputIdentity': textIdentity(jsonEncode(digests)),
      };
      files['busyapi-generation.json'] = Uint8List.fromList(
        utf8.encode('${jsonEncode(metadata)}\n'),
      ).asUnmodifiableView();
      files['BUSYAPI-GENERATION-NOTICE.txt'] = Uint8List.fromList(
        utf8.encode(
          'Produced locally by OpenAPI Generator $generatorVersion (Apache-2.0), https://github.com/OpenAPITools/openapi-generator/tree/v$generatorVersion.\nThis is derived client source, not the canonical contract. Inspect generated headers and dependencies for applicable licensing and compatibility. No generated code or dependency installation was executed by BusyAPI. Generator/JRE code is not included in this export.\n',
        ),
      ).asUnmodifiableView();
      for (final name in [
        'busyapi-generation.json',
        'BUSYAPI-GENERATION-NOTICE.txt',
      ]) {
        digests[name] = await contentIdentityAsync(files[name]!);
      }
      return ClientOutput._(
        this,
        captured,
        files,
        digests,
        generated.executables,
        metadata,
        sanitize('${result.errors}\n${coverage.log}'),
      );
    } on Object catch (error) {
      captured.access.close();
      if (error is OutputAnalysisFailure) rethrow;
      if (error is CoreFailure)
        throw OutputAnalysisFailure(
          error.code,
          error.message,
          captured.checked,
          cause: error,
        );
      throw OutputAnalysisFailure(
        'generate.failed',
        'Client generation failed; source and previous output were preserved',
        captured.checked,
      );
    } finally {
      if (stage != null) await stage.delete(recursive: true);
    }
  }
}
